            m = re.match(r'^#{1,6} (.+)$', line)
            if m: out.add(slug(re.sub(r'[`*]', '', m.group(1))))
        cache[p] = out
    return cache[p]
link = re.compile(r'\]\(([^)\s]+?)\)')
bad = checked = 0
for f in subprocess.run(['git', 'ls-files', '*.md'], capture_output=True, text=True).stdout.split():
    if f.startswith(('specs/', '.hermes/')) or '/changelog/' in f: continue
